import subprocess

# Check what's in base for the key areas
result = subprocess.run(
    ["git", "show", "base:src/marshmallow/schema.py"],
    capture_output=True, text=True
)
content = result.stdout

# Check if dict_class property exists
print("dict_class in base:")
for i, line in enumerate(content.split('\n'), 1):
    if 'dict_class' in line:
        print(f"  {i}: {line}")

# Check if ordered deprecation warning exists
print("\nordered deprecation in base:")
for i, line in enumerate(content.split('\n'), 1):
    if 'deprecated' in line.lower() or 'ordered' in line.lower():
        if i > 80 and i < 130:
            print(f"  {i}: {line}")

# Check if zip_longest is imported
print("\nzip_longest import:")
for i, line in enumerate(content.split('\n'), 1):
    if 'zip_longest' in line:
        print(f"  {i}: {line}")

